"""Readings generated by the engine itself, for UI tests only. Never shipped as lab data."""

from __future__ import annotations

import numpy as np
import pandas as pd

from reactorgenome.engine import cstr, pfr, rtd
from reactorgenome.engine.rate import Kinetics

KIN = Kinetics(k_ref=6.0, T_ref_C=30.0, Ea=45e3)
LAM0 = 10.0
LAM_INF = 0.366 * LAM0


def cstr_table(seed=0) -> pd.DataFrame:
    rng = np.random.default_rng(seed)
    rows = []
    for T in (30.0, 40.0):
        for q in (10.0, 15.0, 20.0, 25.0):
            m = cstr.CSTRModel(V=2.0, qA=q / 60, qB=q / 60, cA_feed=0.1, cB_feed=0.1, T_C=T, kin=KIN)
            sim = cstr.simulate(m, 20.0, 81, init="water")
            row = {"T_C": T, "Q_LPH": 2 * q, "lam0": LAM0}
            for i, t in enumerate((5.0, 10.0, 15.0, 20.0), start=1):
                j = int(np.argmin(np.abs(sim["t"] - t)))
                ca, cc = sim["c_out"][j, 0], sim["c_out"][j, 2]
                lam = cstr.conductivity(ca, cc, m.CA0, LAM0, LAM_INF)
                row[f"t{i}"], row[f"r{i}"] = t, float(lam * (1 + 0.003 * rng.standard_normal()))
            rows.append(row)
    return pd.DataFrame(rows).astype("float64")


def batch_table(seed=1) -> pd.DataFrame:
    rng = np.random.default_rng(seed)
    rows = []
    CA0 = 0.05
    for T in (30.0, 40.0):
        k = KIN.k_C(T)
        for t in np.arange(0, 1260, 60.0):
            CA = CA0 / (1 + k * CA0 * t / 60)
            kap = LAM_INF + (LAM0 - LAM_INF) * CA / CA0
            rows.append({"T_C": T, "t_s": t, "kappa": float(kap * (1 + 0.002 * rng.standard_normal()))})
    return pd.DataFrame(rows).astype("float64")


def pfr_table(seed=2) -> pd.DataFrame:
    rng = np.random.default_rng(seed)
    rows = []
    for T in (30.0, 40.0):
        for q in (10.0, 20.0, 30.0, 40.0):
            m = pfr.PFRModel(V=0.5, Q=2 * q / 60, CA0=0.05, CB0=0.05, T_C=T, kin=KIN)
            X = pfr.solve(m)["X_out"]
            lam = LAM0 * (1 - X) + LAM_INF * X
            row = {"T_C": T, "Q_LPH": 2 * q, "lam0": LAM0}
            for i in range(1, 5):
                row[f"r{i}"] = float(lam * (1 + 0.003 * rng.standard_normal()))
            rows.append(row)
    return pd.DataFrame(rows).astype("float64")


def rtd_table(seed=3) -> pd.DataFrame:
    rng = np.random.default_rng(seed)
    t = np.arange(0, 24.5, 0.5)
    s1 = 20.0 + 800.0 * rtd.E_tanks(t, 4.0, 2.0) * (1 + 0.01 * rng.standard_normal(len(t)))
    s2 = 20.0 + 800.0 * rtd.E_dispersion(t, 5.0, 30.0) * (1 + 0.01 * rng.standard_normal(len(t)))
    return pd.DataFrame({"t_min": t, "s1": s1, "s2": s2, "s3": np.nan, "s4": np.nan}).astype("float64")


def rtd_runs() -> pd.DataFrame:
    return pd.DataFrame({"name": ["Tank 30 LPH", "Bed 30 LPH", "Run 3", "Run 4"], "vessel": ["Stirred tank", "Packed bed", "Stirred tank", "Stirred tank"],
                         "Q_LPH": [30.0, 30.0, 30.0, 30.0], "V_L": [2.0, 2.5, 2.0, 2.0]})
